INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (107716,0,0,'Very well! Let us begin. Perhaps something easy to start. A few imps, perhaps?',12,0,100.0,0,0,0,112636,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (107716,1,0,'Easily defeated, but deadly in large numbers. Perhaps something that hits a little harder...',12,0,100.0,0,0,0,112690,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (107716,2,0,'I expected no less from one who wields crippling ice magic. But how about a foe as skilled in spellcasting as yourself?',12,0,100.0,0,0,0,112698,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (107716,3,0,'Well fought, but Balaadur has been hunting mages for untold ages. Facing him will require mastery of all of your abilities.',12,0,100.0,0,0,0,112701,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (107716,4,0,'For the final piece of the puzzle... a simple stone. A stone from Balaadur\'s realm, left here by chance during one of his many ambushes.',12,0,100.0,0,0,0,112702,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (107716,5,0,'I gave Arrexis a piece so he could attune his ritual to demonic energies. You may have what remains of the stone. May it bring better luck to you.',12,0,100.0,0,0,0,112787,0,'LegionCore');
