INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (108085,0,0,'Millhouse, you certainly are quite talented at getting yourself into a bind!',12,0,100.0,0,0,67659,113231,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (108085,1,0,'Archmage Vargoth is after the Nightborne Soulstone as well. You two should work together to find him before he locates it.',12,0,100.0,0,0,67660,113232,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (108097,0,0,'You\'ve done it! I can feel arcane levels rising in the area. The demons have pulled back for the moment. I\'d wager they plan to hit us hard.',12,0,100.0,0,0,0,113260,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (108097,1,0,'This next part will be complicated. We will need to start the ritual here to draw all that power. While we do that, we will most likely be attacked.',12,0,100.0,0,0,0,0,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (108097,2,0,'We\'ll have to stop casting to fight off the attackers, but will need to get back to it when we can. Once we are close, that is when I expect to be ambushed by Balaadur.',12,0,100.0,0,0,0,0,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (108097,3,0,'Prepare yourself. When you are ready, speak to me and we can begin the incantations.',12,0,100.0,0,0,0,0,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (108097,4,0,'Good! It looks like we are about to be attacked as well. Begin quickly!',12,0,100.0,0,0,0,0,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (108097,5,0,'They are coming, I may need some help!',14,0,100.0,0,0,0,0,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (108097,6,0,'Above you, its forming!',14,0,100.0,0,0,0,0,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (108097,7,0,'We are close! Can you feel it?!',14,0,100.0,0,0,0,0,0,'LegionCore');
